// Deployment configuration. Copy values from your Supabase project
// (Project settings → API). The anon key is designed to be public; access is
// enforced by the database (row-level security + RPC checks), not by hiding it.
//
// On GitHub Pages this file is generated by .github/workflows/deploy.yml from
// the repository variables SUPABASE_URL and SUPABASE_ANON_KEY.
// The local dev server (npm run dev) serves its own config and ignores this file.
window.PAULINO_CONFIG = {
  supabaseUrl: '',      // e.g. 'https://abcdefghijklm.supabase.co'
  supabaseAnonKey: '',  // the project's "anon" / publishable key
  environment: 'production',
  // Optional: photo cut-outs of Paulino per mood, replacing the drawn mascot.
  // mascotImages: { motivational: 'assets/paulino/motivational.png', focused: '…', happy: '…', disappointed: '…', concerned: '…' },
};
